    workspaces: [workspace],
    globalMcpServers: {
      [PLUGIN_KEY]: {
        transport: "stdio",
        command: "bun run docs-server.ts",
        disabled: false,
        plugin: {
          pluginName: "docs-plugin",
          serverName: "docs",
          sourceScope: "global",
          sourceLocation: ".xum/plugins/docs-plugin",
        },
      },
      [LOCAL]: { transport: "stdio", command: "bun run docs-server.ts", disabled: false },
    },
    mcpTestResults: new Map([
