/** The transcript row whose box is the first to cross the scrollport's top edge. */
function topVisibleRowId(scrollport: HTMLElement): string | null {
  const top = scrollport.getBoundingClientRect().top;
  for (const element of scrollport.querySelectorAll<HTMLElement>("[data-message-id]")) {
    if (element.getBoundingClientRect().bottom > top) {
      return element.getAttribute("data-message-id");
    }
  }
  return null;
}

function describeElement(element: Element | null): string {
  if (element === null) return "null";
  const id =
    element.getAttribute("data-message-id") ??
    element.getAttribute("data-testid") ??
    element.getAttribute("role") ??
    element.classList.item(0);
  return id === null ? element.tagName : `${element.tagName}[${id}]`;
}

/**
 * Evidence for #6758, printed only in the assertion messages below. The story failed once in CI
 * (never locally in 36 full-suite runs): the first chunk mounted above the reader without the
 * browser's scroll-anchoring adjustment, so the top row moved by exactly that chunk's height.
 * Each sample is taken in a ResizeObserver callback, after the layout and its anchoring
 * adjustment: `contentHeight/scrollTop/mountedRows`. Running animations and class/style
 * changes on the anchor row or its ancestors are recorded because a change to a property like
 * `transform` there makes Chromium skip that layout's adjustment (an unproven hypothesis).
 */
function recordRevealEvidence(scrollport: HTMLElement, anchor: Element): { stop: () => string } {
  const content = scrollport.querySelector<HTMLElement>('[role="log"]');
  if (content === null) throw new Error("the transcript content element is missing");
  const rows = () => scrollport.querySelectorAll("[data-message-id]").length;
  // Animations inside the scrollport or on its ancestors; the left sidebar's transitions are noise.
  // A "*" marks one on the anchor row or an ancestor of it.
  const transcriptAnimations = () =>
    document.getAnimations().flatMap((animation) => {
      const target = animation.effect instanceof KeyframeEffect ? animation.effect.target : null;
      if (target === null || !(scrollport.contains(target) || target.contains(scrollport))) {
        return [];
      }
      const name =
        animation instanceof CSSAnimation
          ? animation.animationName
          : animation instanceof CSSTransition
            ? animation.transitionProperty
            : "script";
      const onAnchorPath = target.contains(anchor) ? "*" : "";
      return [`${name}@${describeElement(target)}${onAnchorPath}:${animation.playState}`];
    });
  const sample = () => {
    const animations = transcriptAnimations().filter((entry) => entry.includes("*"));
    const height = Math.round(content.getBoundingClientRect().height);
    const geometry = `${height}/${Math.round(scrollport.scrollTop)}/${rows()}`;
    return animations.length === 0 ? geometry : `${geometry} ${animations.join(",")}`;
  };
  const start = sample();
  const samples: string[] = [];
  const resizeObserver = new ResizeObserver(() => {
    if (samples.length < 30) samples.push(sample());
  });
  resizeObserver.observe(content);
  const ancestorChanges: string[] = [];
  const mutationObserver = new MutationObserver((records) => {
    for (const record of records) {
      if (!(record.target instanceof Element) || !record.target.contains(anchor)) continue;
      if (ancestorChanges.length < 10) {
        ancestorChanges.push(`${describeElement(record.target)}.${record.attributeName ?? "?"}`);
      }
    }
  });
  mutationObserver.observe(scrollport, {
    subtree: true,
    attributes: true,
    attributeFilter: ["class", "style"],
  });
  const animations = Array.from(new Set(transcriptAnimations())).slice(0, 10);
  const scrollportBox = scrollport.getBoundingClientRect();
  const topEdge = document.elementFromPoint(
    scrollportBox.left + scrollportBox.width / 2,
    scrollportBox.top + 1
  );
  const atRelease = {
    start,
    overflowAnchor: getComputedStyle(content).overflowAnchor,
    topEdge: describeElement(topEdge),
    activeElement: describeElement(document.activeElement),
    animations,
  };
  return {
    stop: () => {
      resizeObserver.disconnect();
      mutationObserver.disconnect();
      return JSON.stringify({ ...atRelease, samples, ancestorChanges, end: sample() });
    },
  };
}

export const ScrollUpMidReveal: AppStory = {
  render: () => <AppWithMocks setup={setup} />,
  play: async ({ canvasElement, step }) => {
    const canvas = within(canvasElement);
    await findVisibleText(canvasElement, "A short transcript.");
    // Hold the reveal after its tail commit so the scroll happens deterministically mid-reveal;
    // the remaining chunks then run on the production scheduler.
    const held: Array<() => void> = [];
    const realSchedule = transcriptRevealFrameScheduler.schedule;
    transcriptRevealFrameScheduler.schedule = (callback) => {
      held.push(callback);
      return () => {
        const index = held.indexOf(callback);
        if (index !== -1) held.splice(index, 1);
      };
    };
    try {
      await step(
        "Scrolling up while only the tail is mounted keeps the reader's row in place",
        async () => {
          await switchToLargeWorkspace(canvasElement);
          await findVisibleText(canvasElement, rowText(LARGE_ROWS - 1));
          await waitFor(() => expect(held).toHaveLength(1));
          await expect(canvas.queryByText(rowText(0))).toBeNull();
          const scrollport = canvas.getByTestId("message-window");
          await expect(scrollport.scrollHeight).toBeGreaterThan(scrollport.clientHeight);
          // A wheel gesture releases the bottom lock; land in the middle of the mounted tail.
          scrollport.dispatchEvent(new WheelEvent("wheel", { deltaY: -100, bubbles: true }));
          scrollport.scrollTop = Math.floor(scrollport.scrollHeight / 2);
          scrollport.dispatchEvent(new Event("scroll"));
          await canvas.findByRole("button", { name: /Jump to bottom/ });
          const anchorRow = topVisibleRowId(scrollport);
          if (anchorRow === null)
            throw new Error("no transcript row is visible after scrolling up");
          const anchorElement = () => scrollport.querySelector(`[data-message-id="${anchorRow}"]`)!;
          const anchorTop = anchorElement().getBoundingClientRect().top;
          const evidence = recordRevealEvidence(scrollport, anchorElement());

          transcriptRevealFrameScheduler.schedule = realSchedule;
          held.shift()!();
          await waitFor(() => expect(canvas.queryByText(rowText(0))).not.toBeNull(), {
            timeout: 15_000,
          });
          await new Promise<void>((resolve) =>
            requestAnimationFrame(() => requestAnimationFrame(() => resolve()))
          );
          const report = evidence.stop();
          await expect(
            topVisibleRowId(scrollport),
            `top visible row after the reveal; evidence (#6758): ${report}`
          ).toBe(anchorRow);
          // Native scroll anchoring restores the row within a sub-pixel of its previous position.
          await expect(
            Math.abs(anchorElement().getBoundingClientRect().top - anchorTop),
            `anchor row displacement (px); evidence (#6758): ${report}`
          ).toBeLessThanOrEqual(1);
        }
      );
    } finally {
      transcriptRevealFrameScheduler.schedule = realSchedule;
    }
  },
};

const setupOverBudget = () => setup(OVER_BUDGET_ROWS);

const pauseAtBudget: AppStory["play"] = async ({ canvasElement, step }) => {
  const canvas = within(canvasElement);
  await findVisibleText(canvasElement, "A short transcript.");
  // Every mounted transcript row, history-hidden markers included (they have no message id).
  const mountedCount = () =>
    canvasElement.querySelectorAll('[data-testid="message-window"] [data-testid="chat-message"]')
      .length;
  await step("The automatic reveal pauses at its rows budget", async () => {
    await switchToLargeWorkspace(canvasElement);
    await findVisibleText(canvasElement, rowText(OVER_BUDGET_ROWS - 1));
    await waitFor(
      async () => {
        await expect(
          canvasElement.querySelector('[data-testid="message-window"][data-loaded="true"]')
        ).not.toBeNull();
        await expect(mountedCount()).toBeGreaterThanOrEqual(TRANSCRIPT_REVEAL_AUTO_MAX_ROWS);
      },
      { timeout: 15_000 }
    );
    const pausedCount = mountedCount();
    await expect(pausedCount).toBeLessThanOrEqual(
      TRANSCRIPT_REVEAL_AUTO_MAX_ROWS + TRANSCRIPT_REVEAL_CHUNK_ROWS
    );
    // Paused, not merely between chunks: a few more frames mount nothing.
    for (let frame = 0; frame < 4; frame += 1) {
      await new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));
    }
    await expect(mountedCount()).toBe(pausedCount);
    await expect(canvas.queryByText(rowText(0))).toBeNull();
  });
  await step("Load older messages mounts the rest of the loaded rows", async () => {
    const button = await canvas.findByRole("button", { name: "Load older messages" });
    await waitFor(() => expect(button).toBeVisible());
    const pausedCount = mountedCount();
    // The button is only reachable at scrollTop 0, where native scroll anchoring does not
    // apply: the row being read must still stay in place while older rows mount above it.
    const messageWindow = canvasElement.querySelector<HTMLElement>(
      '[data-testid="message-window"]'
    )!;
    // A wheel gesture releases the bottom lock, as a reader scrolling up would.
    messageWindow.dispatchEvent(new WheelEvent("wheel", { deltaY: -100, bubbles: true }));
    messageWindow.scrollTop = 0;
    messageWindow.dispatchEvent(new Event("scroll"));
    await canvas.findByRole("button", { name: /Jump to bottom/ });
    await expect(messageWindow.scrollTop).toBe(0);
    const readRow = messageWindow.querySelector<HTMLElement>("[data-message-id]")!;
    const readRowTop = readRow.getBoundingClientRect().top;
    await userEvent.click(button);
    // Fewer rows than one more budget remain, so the reveal completes; with no older server
    // page to offer, the button goes away.
    await waitFor(() => expect(canvas.queryByText(rowText(0))).not.toBeNull(), {
      timeout: 15_000,
    });
    await expect(mountedCount()).toBeGreaterThan(pausedCount);
    await expect(readRow.isConnected).toBe(true);
    await expect(Math.abs(readRow.getBoundingClientRect().top - readRowTop)).toBeLessThanOrEqual(1);
    await waitFor(() =>
      expect(canvas.queryByRole("button", { name: "Load older messages" })).toBeNull()
    );
  });
};

