// LOCAL PROBE ONLY: never commit. Measures popper geometry on a real WebKit (iPhone Duo simulator).
import { appMeta, AppWithMocks, type AppStory } from "@/browser/stories/meta.js";
import { createMockORPCClient } from "@/browser/stories/mocks/orpc";
import { setupSimpleChatStory } from "@/browser/stories/helpers/chatSetup";
import { createUserMessage, createAssistantMessage } from "@/browser/stories/mocks/messages";
import { openLeftSidebar } from "@/browser/stories/storyPlayHelpers";
import { expandProjects } from "@/browser/stories/helpers/uiState";

export default { ...appMeta, title: "Probe/Duo" };

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const vvEvents: string[] = [];
if (typeof window !== "undefined" && window.visualViewport) {
  const vv = window.visualViewport;
  const rec = (e: Event) =>
    vvEvents.push(
      `${e.type}@${Math.round(performance.now())}:${vv.width}x${vv.height}+${vv.offsetTop}/${vv.pageTop}s${vv.scale}`
    );
  vv.addEventListener("resize", rec);
  vv.addEventListener("scroll", rec);
  window.addEventListener("scroll", () =>
    vvEvents.push(`wscroll@${Math.round(performance.now())}:${window.scrollY}`)
  );
  window.addEventListener("resize", () =>
    vvEvents.push(
      `wresize@${Math.round(performance.now())}:${window.innerWidth}x${window.innerHeight}`
    )
  );
}

function insets() {
  let el = document.getElementById("probe-insets");
  if (!el) {
    el = document.createElement("div");
    el.id = "probe-insets";
    el.style.cssText =
      "position:fixed;visibility:hidden;pointer-events:none;top:0;left:0;padding:env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left)";
    document.body.appendChild(el);
  }
  const cs = getComputedStyle(el);
  return [cs.paddingTop, cs.paddingRight, cs.paddingBottom, cs.paddingLeft].join(",");
}

function metrics() {
  const vv = window.visualViewport;
  return {
    iw: window.innerWidth,
    ih: window.innerHeight,
    cw: document.documentElement.clientWidth,
    ch: document.documentElement.clientHeight,
    bodyH: document.body.getBoundingClientRect().height,
    rootH: document.getElementById("storybook-root")?.getBoundingClientRect().height,
    vv: vv && {
      w: vv.width,
      h: vv.height,
      ot: vv.offsetTop,
      ol: vv.offsetLeft,
      pt: vv.pageTop,
      s: vv.scale,
    },
    sy: window.scrollY,
    scr: `${screen.width}x${screen.height}`,
    dpr: window.devicePixelRatio,
    insets: insets(),
    phone: window.matchMedia("(max-width: 480px) and (pointer: coarse)").matches,
    ua: navigator.userAgent,
    vvEvents: vvEvents.slice(-20),
  };
}

function rectOf(el: Element | null | undefined) {
  if (!el) return null;
  const r = el.getBoundingClientRect();
  return {
    x: Math.round(r.x),
    y: Math.round(r.y),
    w: Math.round(r.width),
    h: Math.round(r.height),
  };
}

function popper() {
  const wrapper = document.querySelector<HTMLElement>("[data-radix-popper-content-wrapper]");
  const content = wrapper?.firstElementChild as HTMLElement | null | undefined;
  return {
    wrapper: rectOf(wrapper),
    wrapperTransform: wrapper?.style.transform,
    content: rectOf(content),
    side: content?.getAttribute("data-side"),
    maxH: content ? getComputedStyle(content).maxHeight : null,
    opacity: content ? getComputedStyle(content).opacity : null,
    avail: wrapper?.style.getPropertyValue("--radix-popper-available-height"),
  };
}

async function log(tag: string, extra: Record<string, unknown> = {}) {
  const body = JSON.stringify({ tag, t: Math.round(performance.now()), m: metrics(), p: popper(), ...extra });
  const wk = (window as unknown as { webkit?: { messageHandlers?: { probe?: { postMessage(b: string): void } } } }).webkit;
  if (wk?.messageHandlers?.probe) {
    wk.messageHandlers.probe.postMessage(body);
    return;
  }
  await fetch("/__probe/log", { method: "POST", body }).catch(() => undefined);
}

async function waitStep(n: number) {
  if ((window as unknown as { webkit?: unknown }).webkit) {
    await sleep(4000);
    return;
  }
  for (;;) {
    const s = await fetch("/__probe/step")
      .then((r) => r.text())
      .catch(() => "0");
    if (Number(s) >= n) return;
    await sleep(1000);
  }
}

async function waitFor<T>(fn: () => T | null | undefined, ms = 20000): Promise<T> {
  const start = Date.now();
  for (;;) {
    const v = fn();
    if (v) return v;
    if (Date.now() - start > ms) throw new Error("timeout");
    await sleep(200);
  }
}

