// Set by VoiceInputEnvApiKey's mock client; its play calls it to drop the key mid-story.
let leaveOnlyCodexOauth: (() => void) | undefined;

/**
 * Transcription resolves OpenAI keys from env vars and key files too, so those enable the mic.
 * Codex OAuth alone cannot transcribe, so once only OAuth is left the mic is disabled again even
 * though the provider still reports isConfigured.
 */
export const VoiceInputEnvApiKey: AppStory = {
  render: () => (
    <AppWithMocks
      setup={() => {
        let openai: ProviderConfigInfo = {
          apiKeySet: false,
          apiKeySource: "env",
          isEnabled: true,
          isConfigured: true,
        };
        const client = setupSimpleChatStory({ workspaceId: "ws-voice-env-key", messages: [] });
        const changes = createAsyncMessageQueue<void>();
        client.providers.getConfig = () => Promise.resolve({ openai });
        client.providers.onConfigChanged = () =>
          Promise.resolve(wrapAsyncIterator(changes.iterate(), {}));
        leaveOnlyCodexOauth = () => {
          // What providerService.getConfig reports for OpenAI with only Codex OAuth tokens.
          openai = { apiKeySet: false, codexOauthSet: true, isEnabled: true, isConfigured: true };
          changes.push();
        };
        return client;
      }}
    />
  ),
  parameters: { ...appMeta.parameters, pixel: PIXEL_DISABLED },
  play: async ({ canvasElement }) => {
    const storyRoot = document.getElementById("storybook-root") ?? canvasElement;
    const canvas = within(storyRoot);
    const mic = await canvas.findByRole("button", { name: /^Voice input/ });
    await waitFor(() => expect(mic).toHaveAccessibleName("Voice input"));
    await expect(mic).toBeEnabled();

    if (!leaveOnlyCodexOauth) throw new Error("mock client was not set up");
    leaveOnlyCodexOauth();
    await waitFor(() => expect(mic).toHaveAccessibleName("Voice input (not configured)"));
    await expect(mic).toBeDisabled();
  },
};

export const ComposerTooltip: AppStory = {
  tags: ["tooltip-visual"],
  globals: {
    viewport: { value: "mobile1", isRotated: false },
  },
  render: () => (
    <AppWithMocks
      setup={() =>
        setupSimpleChatStory({
          workspaceId: "ws-composer-tooltip",
          messages: [],
        })
      }
    />
  ),
  parameters: {
    ...appMeta.parameters,
    pixel: {
      // Keep the shared tooltip honest in the dense composer and near the phone viewport edge.
      matrix: { themes: ["dark", "light"], viewports: ["phone", "laptop"] },
    },
    docs: {
      description: {
        story:
          "Hovers the chat input attachment control so the shared tooltip surface is captured in its most space-constrained production context.",
      },
    },
  },
  play: async ({ canvasElement }) => {
    const storyRoot = document.getElementById("storybook-root") ?? canvasElement;
    await waitForChatInputAutofocusDone(storyRoot);
    blurActiveElement();

    const attachButton = within(storyRoot).getByLabelText("Attach file");
    await userEvent.hover(attachButton);

    await waitFor(
      () => {
        const tooltip = document.querySelector<HTMLElement>(
          "[data-radix-popper-content-wrapper] [data-side]"
        );
        if (!tooltip?.textContent?.includes("Attach any file")) {
          throw new Error("Chat input attachment tooltip not visible");
        }
        if (
          tooltip.scrollWidth > tooltip.clientWidth ||
          tooltip.scrollHeight > tooltip.clientHeight
        ) {
          throw new Error(
            `Tooltip overflows (${tooltip.scrollWidth}×${tooltip.scrollHeight}px > ${tooltip.clientWidth}×${tooltip.clientHeight}px)`
          );
        }

        const bounds = tooltip.getBoundingClientRect();
        const viewportPadding = 8;
        if (
          bounds.left < viewportPadding ||
          bounds.right > window.innerWidth - viewportPadding ||
          bounds.top < viewportPadding ||
          bounds.bottom > window.innerHeight - viewportPadding
        ) {
          throw new Error("Tooltip is outside the viewport-safe area");
        }
      },
      { interval: 50, timeout: 5000 }
    );
  },
};

