    const monitorWakeRows = canvasElement.querySelectorAll<HTMLElement>("[data-bash-monitor-wake]");
    if (monitorWakeRows.length !== 3) {
      throw new Error(`Expected 3 monitor wake rows, found ${monitorWakeRows.length}`);
