              toolCalls: [createWebSearchTool("gallery-miss-search", "deprecatedMuxHelper", 0)],
            }),
            // Scenario 3 (tail): active/pending tools so the elapsed-time UI renders.
            createUserMessage("gallery-active-user", "Inspect the repository", {
