  render: () => (
    <RightSidebarStoryShell
      setup={() => {
        seedSidebarLayout("ws-review-file-filter", ["costs", "review"], "review");
        localStorage.setItem(RIGHT_SIDEBAR_WIDTH_KEY, "700");

        const workspaceId = "ws-review-file-filter";

