export default meta;

type Story = StoryObj<typeof meta>;

export const NewWorkspace: Story = {
  render: () => <CoderWorkspaceFormStory {...getCoderWorkspaceFormProps()} />,
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

